INSERT INTO purpose VALUES('surface-diagnostics','advice::advice','function','Words what a refusal''s reader does about it, one imperative sentence per refusal name, so every face ends the refusal with its help.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-diagnostics','advice::help','module','Names the reason a diagnostic has no help.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-diagnostics','binders::Around','struct','Holds the name the source writes for one binder and the former that opens it, so a face spells a node under the binder it stands under.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-diagnostics','binders::Naming','struct','Holds a lowered module''s roots and where the source writes each binder and each use, so every face spells a node under the binders around it.',NULL,'fits','sound',NULL);
