INSERT INTO purpose VALUES('surface-diagnostics','binders::Scoped','struct','Holds one declaration''s binders with the names the source writes for them, so a node''s type spells under the binders it stands under.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-diagnostics','binders::carry_labels','function','Gives each copy a shift, a settle or a substitution minted its source''s first label, so a type read through a copy spells as written.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-diagnostics','binders::modelled','function','Reads a written model type as the printer spells it, so every face writes a model type as the source does.',NULL,'fits','sound',NULL);
