INSERT INTO purpose VALUES('surface-diagnostics','binders::written_spans','function','Reads the written forms off the origin table, each with where its names are written, so every reader of the forms crosses the table in one place.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-diagnostics','culprit::Culprit','struct','Names what the bytes a refusal''s primary locus covers are, so the underline says what the bytes are rather than whose fact the refusal is.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-diagnostics','frame::Sentence','struct','Holds what a rule of the checking machine was doing to the term it was pushed for, so a context writes it as a clause after `while`.',NULL,'fits','sound',NULL);
