INSERT INTO purpose VALUES('surface-diagnostics','lint::Lint','enum','Names a lint the toolchain knows, a finding about a form the source may write either way, so every face and the driver share one spelling.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-diagnostics','location::Frame','struct','The located frame of one obligation of a failure: its binder names and its locus.',NULL,'fits','sound',NULL);
