INSERT INTO purpose VALUES('surface-diagnostics','model::AnnotationKind','enum','Names what a diagnostic''s annotation marks, so a face lays out each marked span with its role.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-diagnostics','model::Binding','struct','Holds a hypothesis in scope, the name its binder wrote and its type, so a diagnostic names the hypotheses the refusal stood under.',NULL,'fits','sound',NULL);
