INSERT INTO purpose VALUES('surface-diagnostics','obstruction::Obstruction','struct','Holds what obstructs a refused global property, the cells it lives on and its witness, both borrowed from the analysis, so one shape serves every analysis''s refusal.',NULL,'fits','sound',NULL);
