INSERT INTO purpose VALUES('surface-diagnostics','obstruction::parting','function','Reads the parting pair a cell diagnostic holds, by reference, so a refusal of a block''s rules names its peak and both normal forms.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-diagnostics','report::Class','enum','Names what a diagnostic is about and whose fact it records, so a face sorts the diagnostic and a tool matches its class.',NULL,'fits','sound',NULL);
